 if(!all.length){$('homeContent').innerHTML=`<div class="lx-music-app-shell">${side}<main class="lx-music-main lx-music-main-v260">${mobile}${musicEmpty(state.user?.admin?'Sua biblioteca musical está pronta':'Músicas em breve',state.user?.admin?'Cole links oficiais ou envie seus próprios áudios pelo Painel ADM.':'A biblioteca musical está sendo preparada.',state.user?.admin?'<button class="primary-btn" onclick="LX.openAdmin()">Adicionar música</button>':'')}</main></div>`;bindMusicExperience();return}

 let visible=[...all];if(active==='liked')visible=saved;else if(active==='recent')visible=recent;else if(active==='library')visible=[...new Map([...saved,...recent].map(x=>[String(x.id),x])).values()];
