 const featured=all.find(x=>x.featured)||recent[0]||all[0],provider=musicProvider(featured),newest=[...all].sort((a,b)=>+new Date(b.publishedAt||b.createdAt||0)-+new Date(a.publishedAt||a.createdAt||0)).slice(0,12),recommended=(D.recommendation?.(all,h,D.ratings(),D.preferences()[state.user?.email||'']||{})||all).slice(0,12),top=[...all].sort((a,b)=>(b.trending?1:0)-(a.trending?1:0)||(+b.priority||0)-(+a.priority||0)).slice(0,10),genres=[...new Set(all.map(x=>x.genre).filter(Boolean))],quick=(recent.length?recent:top).slice(0,6);
 const now=`<section id="lxMusicNow" class="lx-music-now hidden"><div id="lxMusicNowCover" class="lx-music-now-cover"></div><div><span>TOCANDO AGORA</span><strong id="lxMusicNowTitle">Música</strong><small id="lxMusicNowArtist">LX Music</small></div><button type="button" id="lxMusicNowToggle" onclick="LX.toggleCurrentMusic()" aria-label="Reproduzir ou pausar">▶</button></section>`;
 let content='';
